"use client";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import {
  SelectorGlyph,
  selectorStyle,
  type SelectorShape,
  type SelectorTone,
} from "@/lib/sahajiv/selector";
export type {
  SelectorShape,
  SelectorTone,
} from "@/lib/sahajiv/selector";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Label, type LabelProps } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
export const questionnaireVariants = cva("v-quest grid gap-[28px]");
export type QuestionnaireProps = React.ComponentProps<"div">;
export function Questionnaire({ className, ...props }: QuestionnaireProps) {
  return (
    <div
      data-slot="questionnaire"
      data-part="root"
      className={cn(questionnaireVariants(), className)}
      {...props}
    />
  );
}
export type QuestionnaireProgressProps = React.ComponentProps<"div"> & {
  value: number;
  total: number;
};
export function QuestionnaireProgress({
  value,
  total,
  className,
  children,
  ...props
}: QuestionnaireProgressProps) {
  const maximum = Math.max(0, Number.isFinite(total) ? total : 0);
  const current = Math.max(
    0,
    Math.min(maximum, Number.isFinite(value) ? value : 0),
  );
  return (
    <div
      data-slot="questionnaire-progress"
      className={cn(
        "v-quest__progress flex items-center gap-[12px] text-[13px] text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    >
      {children ?? (
        <>
          <b>
            {current} of {maximum}
          </b>
          <Progress value={maximum > 0 ? (current / maximum) * 100 : 0} />
        </>
      )}
    </div>
  );
}
export type QuestionnaireQuestionProps = React.ComponentProps<"fieldset">;
export function QuestionnaireQuestion({
  className,
  ...props
}: QuestionnaireQuestionProps) {
  return (
    <fieldset
      data-slot="questionnaire-question"
      className={cn(
        "v-quest__q grid min-w-0 gap-[12px] [border:0] p-0 bg-transparent [box-shadow:none]",
        className,
      )}
      {...props}
    />
  );
}
export type QuestionnaireLabelProps = LabelProps;
export function QuestionnaireLabel({
  className,
  ...props
}: QuestionnaireLabelProps) {
  return (
    <Label
      data-slot="questionnaire-label"
      className={cn("[font-size:17px] [font-weight:600]", className)}
      {...props}
    />
  );
}
type ChoiceContext = {
  name: string;
  selectorShape: SelectorShape;
  selectorTone: SelectorTone;
  value?: string;
  change: (value: string) => void;
};
const ChoiceContext = React.createContext<ChoiceContext | null>(null);
export type QuestionnaireOptionsProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue"
> & {
  name?: string;
  selectorShape?: SelectorShape;
  selectorTone?: SelectorTone;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};
export function QuestionnaireOptions({
  ref,
  className,
  name,
  selectorShape = "organic",
  selectorTone = "pink",
  value,
  defaultValue,
  onValueChange,
  children,
  ...props
}: QuestionnaireOptionsProps) {
  const id = React.useId();
  const [local, setLocal] = React.useState(defaultValue);
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  return (
    <ChoiceContext.Provider
      value={{
        name: name ?? id,
        selectorShape,
        selectorTone,
        value: value ?? local,
        change: (next) => {
          if (value === undefined) setLocal(next);
          onValueChange?.(next);
        },
      }}
    >
      <div
        ref={flowRef}
        data-slot="questionnaire-options"
        className={cn("v-quest__opts grid gap-[8px]", className)}
        role="radiogroup"
        {...props}
      >
        {children}
      </div>
    </ChoiceContext.Provider>
  );
}
export type QuestionnaireOptionProps = React.ComponentProps<"label"> & {
  value: string;
  disabled?: boolean;
  selectorShape?: SelectorShape;
  selectorTone?: SelectorTone;
  inputProps?: Omit<React.ComponentProps<"input">, "value" | "type">;
};
export function QuestionnaireOption({
  ref: externalMorphRef,
  value,
  disabled,
  selectorShape,
  selectorTone,
  style,
  inputProps,
  className,
  children,
  ...props
}: QuestionnaireOptionProps) {
  const context = React.useContext(ChoiceContext);
  if (!context)
    throw new Error("QuestionnaireOption must be inside QuestionnaireOptions");
  const ownedMorphRef = useMorph<HTMLLabelElement>("cards", externalMorphRef);
  const shape = selectorShape ?? context.selectorShape;
  const tone = selectorTone ?? context.selectorTone;
  return (
    <label
      ref={ownedMorphRef}
      style={selectorStyle(tone, style)}
      data-selector-shape={shape}
      data-slot="questionnaire-option"
      data-state={context.value === value ? "checked" : "unchecked"}
      className={cn(
        "v-quest__opt grid grid-cols-[36px_minmax(0,1fr)_28px] items-center gap-[14px] min-h-[64px] pt-[14px] pr-[16px] pb-[14px] pl-[14px] rounded-[20px] bg-[var(--v-canvas)] cursor-pointer",
        className,
      )}
      {...props}
    >
      <input
        data-slot="questionnaire-option-input"
        type="radio"
        name={context.name}
        value={value}
        checked={context.value === value}
        disabled={disabled}
        {...inputProps}
        onChange={(event) => {
          inputProps?.onChange?.(event);
          if (!event.defaultPrevented && event.target.checked)
            context.change(value);
        }}
      />
      <span data-slot="questionnaire-selector">
        <SelectorGlyph
          shape={shape}
          tone={tone}
          state={context.value === value}
          disabled={disabled || inputProps?.disabled}
        />
      </span>
      {children}
    </label>
  );
}
export type QuestionnaireOptionBodyProps = React.ComponentProps<"span">;
export function QuestionnaireOptionBody({
  className,
  ...props
}: QuestionnaireOptionBodyProps) {
  return (
    <span
      data-slot="questionnaire-option-body"
      className={cn(
        "v-quest__opt-body order-2 grid gap-[2px] min-w-0",
        className,
      )}
      {...props}
    />
  );
}

export type QuestionnaireWeekdaysProps = React.ComponentProps<"div">;
export function QuestionnaireWeekdays({
  ref,
  className,
  ...props
}: QuestionnaireWeekdaysProps) {
  const flowRef = useFlowGroup<HTMLDivElement>(ref);
  return (
    <div
      ref={flowRef}
      data-slot="questionnaire-weekdays"
      className={cn("v-weekdays flex gap-[6px]", className)}
      {...props}
    />
  );
}
export type QuestionnaireWeekdayProps = React.ComponentProps<"label">;
export function QuestionnaireWeekday({
  className,
  ...props
}: QuestionnaireWeekdayProps) {
  return (
    <label
      data-slot="questionnaire-weekday"
      className={cn(
        "relative grid place-items-center size-[40px] [border-radius:50%] text-[11.5px] font-semibold bg-[var(--card)] text-[color:var(--v-text-2)] cursor-pointer",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import * as React from "react";
import { AnimatePresence, motion } from "motion/react";
import { shapeContour, signatureShapePaths } from "@/lib/sahajiv/signature-shapes";
import { useChoreography } from "@/lib/sahajiv-motion/choreography";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";

export type SelectorShape =
  "organic" | "rounded" | "circle" | "pebble" | "leaf" | "flower";
export type SelectorTone = "pink" | "blue" | "olive" | "yellow";
export const selectorShapes: SelectorShape[] = [
  "organic",
  "pebble",
  "rounded",
  "circle",
  "leaf",
  "flower",
];
export const selectorTones: SelectorTone[] = [
  "pink",
  "blue",
  "olive",
  "yellow",
];
const contour = (radius: (angle: number) => number) =>
  shapeContour((angle) => [
    50 + radius(angle) * Math.cos(angle),
    50 + radius(angle) * Math.sin(angle),
  ]);
const paths: Record<SelectorShape, string> = {
  organic: contour((t) => 41 + 1.1 * Math.cos(3 * t + 0.6)),
  rounded: contour(
    (t) =>
      40 /
      Math.pow(Math.abs(Math.cos(t)) ** 5 + Math.abs(Math.sin(t)) ** 5, 1 / 5),
  ),
  circle: contour(() => 41),
  pebble: signatureShapePaths["pebble-soft"],
  leaf: shapeContour((t) => {
    const x = 38 * Math.cos(t),
      y = 30 * Math.sin(t) * (1 + 0.22 * Math.cos(t));
    return [50 + (x - y) * 0.707, 50 + (x + y) * 0.707];
  }),
  flower: contour((t) => 37 + 5 * Math.cos(5 * t - Math.PI / 2)),
};
export function selectorStyle(
  tone: SelectorTone,
  style?: React.CSSProperties,
): React.CSSProperties {
  return {
    "--selector-accent": `var(--v-${tone})`,
    ...style,
  } as React.CSSProperties;
}
/** A single silhouette/mark renderer for native and Radix selection semantics. */
export function SelectorGlyph({
  shape = "organic",
  tone = "pink",
  state,
  kind = "radio",
  disabled = false,
}: {
  shape?: SelectorShape;
  tone?: SelectorTone;
  state: boolean | "indeterminate";
  kind?: "checkbox" | "radio";
  disabled?: boolean;
}) {
  const { quiet, transition } = useChoreography();
  const surface = React.useRef<HTMLSpanElement>(null);
  const morphRef = useMorph<HTMLSpanElement>("controls", surface);
  React.useEffect(() => {
    const node = surface.current;
    const owner = node?.closest('[role="checkbox"], [role="radio"], label');
    if (!node || !owner) return;
    const controller = new AbortController();
    for (const type of ["keydown", "keyup"] as const)
      owner.addEventListener(
        type,
        (event) => {
          const key = (event as KeyboardEvent).key;
          if (key === " " || key === "Enter")
            node.dispatchEvent(new KeyboardEvent(type, { key }));
        },
        { signal: controller.signal },
      );
    for (const type of ["focusin", "focusout"] as const)
      owner.addEventListener(
        type,
        () => node.dispatchEvent(new FocusEvent(type)),
        { signal: controller.signal },
      );
    return () => controller.abort();
  }, []);
  const active = state === true || state === "indeterminate";
  const fill = disabled
    ? "var(--v-disabled-face)"
    : active
      ? `var(--v-${tone})`
      : "var(--v-canvas)";
  const ink = disabled ? "var(--v-disabled-ink)" : "var(--ink-fixed)";
  const stroke = disabled
    ? "var(--v-disabled-edge)"
    : active
      ? ink
      : "var(--v-text-2)";
  const mappedShape = {
    rounded: "squircle",
    circle: "circle",
    pebble: "pebble",
    leaf: "leaf",
    flower: "flower-5",
  };
  return (
    <span
      data-slot="selector-glyph"
      data-selector-shape={shape}
      data-selector-tone={tone}
      data-motion-quiet={quiet || undefined}
      aria-hidden="true"
      style={{
        display: "inline-grid",
        position: "relative",
        placeItems: "center",
        width: "var(--selector-size,28px)",
        height: "var(--selector-size,28px)",
        flexShrink: 0,
      }}
    >
      <span
        ref={morphRef}
        data-slot="selector-surface-host"
        data-morph="both"
        data-tier="tile"
        data-shape={shape === "organic" ? undefined : mappedShape[shape]}
        data-depth={shape === "organic" ? 0.018 : 0}
        data-lobes={shape === "organic" ? 3 : 0}
        data-asym=".1"
        data-r="12"
        data-sw={active ? "1.25" : "1.5"}
        data-motion={quiet || disabled ? "off" : undefined}
        aria-disabled={disabled || undefined}
        style={
          {
            position: "absolute",
            width: "calc(var(--selector-size,28px) - 4px)",
            height: "calc(var(--selector-size,28px) - 4px)",
            borderRadius: "48% 52% 50% 50%",
            "--mfill": fill,
            "--mstroke": stroke,
          } as React.CSSProperties
        }
      />
      <motion.svg
        data-slot="selector-drawing"
        aria-hidden="true"
        focusable="false"
        viewBox="0 0 100 100"
        width="100%"
        height="100%"
        style={{ display: "block", overflow: "visible", flexShrink: 0 }}
      >
        <motion.path
          data-slot="selector-surface"
          d={paths[shape]}
          initial={false}
          animate={{ d: paths[shape], scale: 1 }}
          transition={transition}
          fill={fill}
          stroke={
            disabled
              ? "var(--v-disabled-edge)"
              : active
                ? ink
                : "var(--v-text-2)"
          }
          strokeWidth={active ? 1.25 : 1.5}
          vectorEffect="non-scaling-stroke"
        />
        <AnimatePresence initial={false}>
          {active && (
            <motion.g
              key={String(state)}
              data-slot="selector-mark"
              initial={quiet ? false : { opacity: 0, scale: 0.55 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: quiet ? 1 : 0.55 }}
              transition={transition}
              style={{ transformOrigin: "50px 50px" }}
            >
              {state === "indeterminate" ? (
                <path
                  d="M32 50H68"
                  stroke={ink}
                  strokeWidth="9"
                  strokeLinecap="round"
                />
              ) : kind === "checkbox" ? (
                <path
                  d="M28 50 43 65 73 35"
                  fill="none"
                  stroke={ink}
                  strokeWidth="8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              ) : (
                <circle cx="50" cy="50" r="13" fill={ink} />
              )}
            </motion.g>
          )}
        </AnimatePresence>
      </motion.svg>
    </span>
  );
}

@layer sahajiv-states {
[data-slot="questionnaire-progress"] b {
  color: var(--v-text);
}
[data-slot="questionnaire-progress"] .v-track {
  flex: 1;
  min-width: 80px;
}
[data-slot="questionnaire-option"] {
  transition:
    background var(--t-element),
    box-shadow var(--t-element),
    transform var(--t-micro) var(--enter);
}
[data-slot="questionnaire-option"]:not(:has(input:checked)) {
  box-shadow: inset 0 0 0 1px var(--v-border);
}
[data-slot="questionnaire-option"]:not(:has(input:checked)):hover {
  background: var(--v-beige-2);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
[data-slot="questionnaire-option"]:active {
  transform: scale(0.99);
}
[data-slot="questionnaire-option"] input {
  order: 3;
  appearance: none;
  width: 22px;
  height: 22px;
  margin: 0;
  border-radius: 50%;
  border: 1.5px solid var(--v-edge);
  background: var(--v-canvas);
  display: grid;
  place-items: center;
  transition:
    background var(--t-micro),
    border-color var(--t-micro);
}
[data-slot="questionnaire-option"] .v-disk[data-slot] {
  order: 1;
  width: 36px;
  height: 36px;
}
[data-slot="questionnaire-option"] input:checked {
  background:
    radial-gradient(circle, var(--ink-fixed) 0 4px, transparent 4.6px),
    var(--v-pink);
  border-color: var(--v-pink);
  border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  animation: v-questionnaire-tick var(--t-max) var(--enter) both;
}
[data-slot="questionnaire-options"]:not(.v-glide)
  [data-slot="questionnaire-option"]:has(input:checked) {
  background: var(--v-pink-soft);
  color: var(--v-text);
  box-shadow: none;
}
[data-slot="questionnaire-option"]:has(input:checked) .v-quest__opt-body small {
  color: var(--v-text);
}
[data-slot="questionnaire-option"]:has(input:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
[data-slot="questionnaire-option-body"] b {
  font-weight: 600;
  font-size: 15px;
  line-height: 1.3;
}
[data-slot="questionnaire-option-body"] small {
  font-size: 13px;
  color: var(--v-text-2);
  line-height: 1.4;
}
[data-slot="questionnaire-option"]:has(input:disabled) {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
:root[data-mode="dark"] [data-slot="questionnaire-option"] {
  background: var(--v-beige);
}
:root[data-mode="dark"] [data-slot="questionnaire-option"] input {
  border-color: var(--v-text-2);
  background: var(--v-beige-2);
}
:root[data-mode="dark"] [data-slot="questionnaire-option"] input:checked {
  background:
    radial-gradient(circle, var(--ink-fixed) 0 4px, transparent 4.6px),
    var(--v-pink);
  border-color: var(--v-pink);
}
@keyframes v-questionnaire-tick {
  0% {
    transform: scale(0.8);
    border-radius: 54% 46% 50% 50%/46% 50% 50% 54%;
  }
  55% {
    transform: scale(1.14, 0.94);
    border-radius: 50% 50% 46% 54%/54% 50% 46% 50%;
  }
  80% {
    transform: scale(0.98, 1.04);
  }
  100% {
    transform: scale(1);
    border-radius: 46% 54% 50% 50%/50% 46% 54% 50%;
  }
}

[data-slot="questionnaire-weekday"] { transition: background var(--t-micro), color var(--t-micro); }
[data-slot="questionnaire-weekday"] input { position: absolute; opacity: 0; inset: 0; margin: 0; }
[data-slot="questionnaire-weekday"]:hover { background: color-mix(in oklab,var(--card) 90%,var(--v-ink)); color: var(--v-text); }
[data-slot="questionnaire-weekday"]:has(input:checked) { background: var(--v-pink); color: var(--v-on-accent); }
[data-slot="questionnaire-weekday"]:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 2px; }
@media (max-width: 640px) { [data-slot="questionnaire-weekday"] { flex: 1 1 0; min-width: 0; aspect-ratio: 1; } }
:root[data-mode="dark"] [data-slot="questionnaire-weekday"] { background: var(--v-beige); }

/* The native input remains the focus/form owner; the same organic selector used
   by RadioGroup paints its checked state without replacing native behaviour. */
[data-slot="questionnaire-option"] { position:relative; border-radius:16px; }
[data-slot="questionnaire-option"] [data-slot="questionnaire-option-input"] { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); clip-path:inset(50%); border:0; white-space:nowrap; }
[data-slot="questionnaire-selector"] { order:3; display:inline-grid; width:28px; height:28px; }
[data-slot="questionnaire-option-body"] { overflow-wrap:anywhere; }
[data-slot="questionnaire-option"]:not(:has(.v-disk)) { grid-template-columns:minmax(0,1fr) 28px; }
[data-slot="questionnaire-option"]:has(input:disabled) { background:var(--v-disabled-face); }

/* The shared Button body engine owns the moving selector contour. The original
   SVG is the immediate SSR/Off/reduced fallback; the mark stays above either. */
[data-slot="selector-glyph"]:has([data-slot="selector-surface-host"] > svg.v-morph) [data-slot="selector-surface"] { opacity:0; }
[data-slot="selector-drawing"] { position:relative; pointer-events:none; }

[data-slot="questionnaire-question"] > legend { margin-bottom:12px; }

}
